const output = $input.first().json.output;

const processOutput = (data) => {
  let result = data;
  try {
    if (typeof result === 'string' && result.trim().startsWith('{') && result.trim().endsWith('}')) {
      const parsed = JSON.parse(result);
      if (parsed.mensagem) result = parsed.mensagem;
    } else {
      result = JSON.parse(result);
    }
  } catch (error) {}

  if (typeof result === 'string' && result.includes('"mensagem":')) {
    result = result.split('"mensagem":')[1];
  }
  if (typeof result === 'string') {
    result = result.trim().replace(/^"+|"+$/g, '');
  }
  return result;
};

const cleanOutput = processOutput(output);
const splitMessages = cleanOutput.split('\n').map(msg => msg.trim()).filter(msg => msg.length > 0);

return { messages: splitMessages };

function limparMensagem(texto) {
  if (typeof texto !== 'string') return '';
  let resultado = texto
    .replace(/"response_metadata"\s*:\s*{[^}]*}/g, '')
    .replace(/"additional_kwargs"\s*:\s*{[^}]*}/g, '')
    .replace(/"tool_calls"\s*:\s*\[\s*\]/g, '')
    .replace(/"invalid_tool_calls"\s*:\s*\[\s*\]/g, '')
    .replace(/"type"\s*:\s*"(ai|human)"/g, '')
    .replace(/,\s*{[^}]*}/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return resultado;
}

function processarMensagens(items) {
  return items.map(item => {
    if (!item?.json?.mensagem) return item;
    let mensagem = item.json.mensagem;
    if (typeof mensagem === 'object') {
      try { mensagem = JSON.stringify(mensagem); } catch(e) { return item; }
    }
    const mensagemLimpa = limparMensagem(mensagem);
    if (mensagemLimpa && mensagemLimpa.length > 0) item.json.mensagem = mensagemLimpa;
    return { json: item.json };
  });
}

try {
  const items = $input.all();
  return processarMensagens(items);
} catch (error) {
  throw error;
}

const input = $input.first().json;
const message = input.messages?.[0];
const contact = input.contacts?.[0];
const metadata = input.metadata;

if (!message) return [];

const msgType = message.type || 'unknown';
let textContent = '';
if (msgType === 'text') {
  textContent = message.text?.body || '';
} else if (msgType === 'interactive') {
  textContent = message.interactive?.button_reply?.title || message.interactive?.list_reply?.title || '';
} else if (msgType === 'button') {
  textContent = message.button?.text || '';
}

const caption = message.image?.caption || message.video?.caption || message.document?.caption || '';

return {
  json: {
    remoteJid: message.from,
    pushName: contact?.profile?.name || '',
    phoneNumberId: metadata?.phone_number_id || '',
    messageId: message.id,
    timestamp: message.timestamp,
    messageType: msgType,
    conversation: textContent,
    caption: caption,
    isAudio: msgType === 'audio',
    isImage: msgType === 'image',
    isDocument: msgType === 'document',
    isText: msgType === 'text',
    isReaction: msgType === 'reaction',
    isSticker: msgType === 'sticker',
    mediaId: message.audio?.id || message.image?.id || message.document?.id || message.video?.id || message.sticker?.id || null,
    mediaMimeType: message.audio?.mime_type || message.image?.mime_type || message.document?.mime_type || message.video?.mime_type || null,
    documentFileName: message.document?.filename || null,
    contextMessageId: message.context?.id || null,
    extendedText: message.context ? textContent : null,
    _raw: message
  }
};
